<template><main class="page"><section class="hero"><div class="wrap"><NuxtLink to="/spec-library" class="back">← Spec Library</NuxtLink><div class="kicker">BROWSE HISTORICAL SPECIFICATIONS</div><h1>Manufacturers &amp; Models</h1><p>Browse the complete historical specification index by manufacturer and model.</p></div></section><section class="wrap section"><div v-for="m in directory" :key="m.name" class="manufacturer"><h2><NuxtLink :to="'/spec-library/manufacturers/'+slug(m.name)">{{m.name}}</NuxtLink></h2><div class="models"><span v-for="model in m.models" :key="model">{{model}}</span></div></div></section></main></template><script setup>
import historicalMachines from '~/assets/data/historical-machines.json'
const clean=s=>String(s||'').trim()
const slug=s=>clean(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')
const rows=historicalMachines.filter(m=>clean(m.Manufacturer)&&clean(m.Model)&&clean(m.WebDesc||m.Web_Desc))
const directory=[...new Set(rows.map(m=>clean(m.Manufacturer)))].sort((a,b)=>a.localeCompare(b)).map(name=>({name,models:[...new Set(rows.filter(m=>clean(m.Manufacturer)===name).map(m=>clean(m.Model)))].sort((a,b)=>a.localeCompare(b))}))
useSeoMeta({title:'Machine Manufacturers & Models | UMS Spec Library',description:'Browse historical machinery manufacturers and models in the Used Machinery Source Spec Library.'})
</script><style scoped>.page{color:#17273a;padding-bottom:60px}.wrap{max-width:1200px;margin:auto;padding:0 28px}.hero{background:#0b2545;color:#fff;padding:46px 0;border-bottom:4px solid #f47b20}.back{color:#c8d9eb}.kicker{color:#f47b20;font-size:.78rem;font-weight:900;letter-spacing:.12em;margin:16px 0 8px}.hero h1{font-size:3rem;margin:0}.section{padding-top:34px}.manufacturer{margin-bottom:28px}.manufacturer h2{margin-bottom:10px}.manufacturer h2 a{color:#0b2545}.models{display:flex;flex-wrap:wrap;gap:7px 16px;color:#526579}@media(max-width:800px){.wrap{padding:0 18px}}</style>